contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val) public payable {
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted == false && c.MinSum() == val || reverted == true && c.MinSum() == beforeMinSum);
    }

    receive() external payable {}
}

